impl BlockSoundType {
    #[doc = r" Vanilla `BlockState.getSoundType` for a block and one of its states."]
    #[must_use]
    pub fn of(block: BlockId, state: BlockStateId) -> &'static Self {
        let index = match state.as_u16() {
            35443u16 => 126usize,
            35444u16 => 126usize,
            35445u16 => 126usize,
            35446u16 => 126usize,
            35447u16 => 126usize,
            35448u16 => 126usize,
            35449u16 => 126usize,
            35450u16 => 126usize,
            _ => BLOCK_SOUND_TYPE_BY_BLOCK[block.as_u16() as usize] as usize,
        };
        &BLOCK_SOUND_TYPES[index]
    }
}
